141	class ClaudeStreamingAdapter {
142	    constructor(writeLine, onEvent, rootPath, providerConversationId) {
143	        this.writeLine = writeLine;
144	        this.onEvent = onEvent;
145	        this.pendingApprovals = new Map();
146	        this.pendingQuestions = new Map();
147	        this.providerConversationId = providerConversationId;
148	        this.rootPath = rootPath;
149	        this.activeBlocks = new Map();
150	        this.streamedTextItems = new Map();
151	        this.activeMessageId = null;
152	        this.protocolErrorSequence = 1;
153	        this.turnStarted = false;
154	        this.turnHasAssistantText = false;
155	    }
156	
157	    async start(prompt) {
158	        await this.sendMessage(prompt);
159	    }
160	
161	    async sendMessage(content) {
162	        await this.writeLine(claudeUserMessage(requireMessage(content)));
163	    }
164	
165	    async answerQuestion(requestId, answers) {
166	        const pendingQuestion = this.pendingQuestions.get(requestId);
167	        if (!pendingQuestion) throw new Error(`Unknown Claude question request id: ${requestId}`);
168	        const mappedAnswers = Object.fromEntries(pendingQuestion.questions.map(({ id, question }) => {
169	            if (!Object.hasOwn(answers, id)) throw new Error(`Missing answer for Claude question: ${id}`);
170	
171	            return [question, answers[id]];
172	        }));
173	        const updatedInput = { ...pendingQuestion.input, answers: mappedAnswers };
174	        const response = { behavior: 'allow', toolUseID: pendingQuestion.toolUseId, updatedInput };
175	        await this.writeLine(claudeControlResponse(requestId, response));
176	        this.pendingQuestions.delete(requestId);
177	    }
178	
179	    async answerApproval(requestId, decision) {
180	        const pendingApproval = this.pendingApprovals.get(requestId);
181	        if (!pendingApproval) throw new Error(`Unknown or stale Claude approval request id: ${requestId}`);
182	        if (pendingApproval.submitted) throw new Error(`Claude approval request was already submitted: ${requestId}`);
183	        if (!pendingApproval.approval.availableDecisions.includes(decision)) {
184	            throw new Error(`Unsupported Claude approval decision for request ${requestId}`);
185	        }
186	        const response = claudeApprovalResponse(pendingApproval, decision);
187	        pendingApproval.submitted = true;
188	        try {
189	            await this.writeLine(claudeControlResponse(requestId, response));
190	        } catch (error) {
191	            pendingApproval.submitted = false;
192	            throw error;
193	        }
194	        await this.onEvent({ requestId, type: 'approvalSubmitted' });
195	        this.pendingApprovals.delete(requestId);
196	        await this.onEvent({ requestId, type: 'approvalResolved' });
197	    }
198	
199	    async handleMessage(event) {
200	        const questionRequest = claudeQuestionRequest(event);
201	        if (questionRequest) {
202	            this.pendingQuestions.set(questionRequest.requestId, questionRequest);
203	            await this.onEvent({
204	                questions: questionRequest.questions,
205	                requestId: questionRequest.requestId,
206	                type: 'question',
207	            });
208	            return;
209	        }
210	        const approvalRequest = claudeApprovalRequest(event);
211	        if (approvalRequest) {
212	            if (this.pendingApprovals.has(approvalRequest.approval.requestId)) {
213	                throw new Error(`Duplicate Claude approval request id: ${approvalRequest.approval.requestId}`);
214	            }
215	            this.pendingApprovals.set(approvalRequest.approval.requestId, { ...approvalRequest, submitted: false });
216	            await this.onEvent({ approval: approvalRequest.approval, type: 'approval' });
217	            return;
218	        }
219	        if (event.type === 'control_request' && event.request?.subtype === 'can_use_tool') {
220	            throw new Error('Invalid Claude question request');
221	        }
222	        if (event.type === 'system' && typeof event.session_id === 'string') {
223	            await this.onEvent({ conversationId: event.session_id, type: 'sessionStarted' });
224	        }
225	        if (event.type === 'system') {
226	            if (event.subtype !== 'init') ClaudeStreamingAdapter.ignoreProtocolNoise();
227	            return;
228	        }
229	        if (event.type === 'stream_event') {
230	            await this.handleStreamEvent(event.event);
231	            return;
232	        }
233	        if (event.type === 'assistant') {
234	            await this.handleAssistantCompletion(event);
235	            return;
236	        }
237	        if (event.type === 'user') {
238	            await this.ensureTurnStarted();
239	            await this.handleToolResults(event);
240	            return;
241	        }
242	        if (event.type === 'result') {
243	            await this.handleResult(event);
244	            return;
245	        }
246	        ClaudeStreamingAdapter.ignoreProtocolNoise();
247	    }
248	
249	    async ensureTurnStarted() {
250	        if (this.turnStarted) return;
251	        this.turnStarted = true;
252	        await this.onEvent({ type: 'turnStarted' });
253	    }
254	
255	    async handleStreamEvent(streamEvent) {
256	        if (!streamEvent || typeof streamEvent.type !== 'string') {
257	            await this.emitProtocolError('invalid stream event');
258	            return;
259	        }
260	        if (streamEvent.type === 'message_start') {
261	            await this.ensureTurnStarted();
262	            this.activeMessageId = streamEvent.message?.id;
263	            this.activeBlocks.clear();
264	            if (typeof this.activeMessageId !== 'string' || this.activeMessageId.length === 0) {
265	                await this.emitProtocolError('message_start missing message id');
266	            }
267	            return;
268	        }
269	        if (streamEvent.type === 'content_block_start') {
270	            await this.handleContentBlockStart(streamEvent);
271	            return;
272	        }
273	        if (streamEvent.type === 'content_block_delta') {
274	            await this.handleContentBlockDelta(streamEvent);
275	            return;
276	        }
277	        if (streamEvent.type === 'content_block_stop' || streamEvent.type === 'message_delta' || streamEvent.type === 'message_stop') return;
278	        ClaudeStreamingAdapter.ignoreProtocolNoise();
279	    }
280	
281	    async handleContentBlockStart(streamEvent) {
282	        const validBlock = !!streamEvent.content_block
283	            && typeof streamEvent.content_block === 'object'
284	            && !Array.isArray(streamEvent.content_block);
285	        if (!Number.isSafeInteger(streamEvent.index) || !validBlock || typeof this.activeMessageId !== 'string' || this.activeMessageId.length === 0) {
286	            await this.emitProtocolError('invalid content_block_start');
287	            return;
288	        }
289	        const block = structuredClone(streamEvent.content_block);
290	        const providerItemId = block.id ?? `${this.activeMessageId}:${block.type}:${streamEvent.index}`;
291	        const separator = block.type === 'text' && this.turnHasAssistantText ? '\n\n' : '';
292	        const trackedBlock = { block, inputJson: '', providerItemId, separator, text: block.text ?? block.thinking ?? '' };
293	        this.activeBlocks.set(streamEvent.index, trackedBlock);
294	        if (block.type === 'text') {
295	            // Keyed by stable providerItemId so the later aggregated `assistant` message reconciles
296	            // even after `message_start` of the next step has cleared `activeBlocks`.
297	            this.streamedTextItems.set(providerItemId, { separator });
298	            await this.onEvent({ itemId: providerItemId, type: 'assistantStarted' });
299	            if (separator.length > 0) await this.onEvent({ content: separator, itemId: providerItemId, type: 'assistant' });
300	            return;
301	        }
302	        if (block.type === 'thinking') {
303	            const event = {
304	                ...eventBase(providerItemId, 'reasoning', 'Thinking'),
305	                content: trackedBlock.text,
306	                details: [trackedBlock.text],
307	                summary: [],
308	            };
309	            await this.onEvent({ event, type: 'event' });
310	            return;
311	        }
312	        if (block.type === 'tool_use') await this.onEvent({ event: claudeToolEvent(block, 'inProgress', providerItemId), type: 'event' });
313	    }
314	
315	    async handleContentBlockDelta(streamEvent) {
316	        const trackedBlock = this.activeBlocks.get(streamEvent.index);
317	        if (!trackedBlock || !streamEvent.delta || typeof streamEvent.delta.type !== 'string') {
318	            await this.emitProtocolError('invalid content_block_delta');
319	            return;
320	        }
321	        const { delta } = streamEvent;
322	        if (delta.type === 'text_delta' && typeof delta.text === 'string' && trackedBlock.block.type === 'text') {
323	            trackedBlock.text += delta.text;
324	            this.turnHasAssistantText = this.turnHasAssistantText || delta.text.length > 0;
325	            await this.onEvent({ content: delta.text, itemId: trackedBlock.providerItemId, type: 'assistant' });
326	            return;
327	        }
328	        if (delta.type === 'thinking_delta' && typeof delta.thinking === 'string' && trackedBlock.block.type === 'thinking') {
329	            trackedBlock.text += delta.thinking;
330	            const event = {
331	                ...eventBase(trackedBlock.providerItemId, 'reasoning', 'Thinking'),
332	                content: trackedBlock.text,
333	                details: [trackedBlock.text],
334	                summary: [],
335	            };
336	            await this.onEvent({ event, type: 'event' });
337	            return;
338	        }
339	        if (delta.type === 'input_json_delta' && typeof delta.partial_json === 'string' && trackedBlock.block.type === 'tool_use') {
340	            trackedBlock.inputJson += delta.partial_json;
341	            const updatedBlock = { ...trackedBlock.block, input: trackedBlock.inputJson };
342	            await this.onEvent({ event: claudeToolEvent(updatedBlock, 'inProgress', trackedBlock.providerItemId), type: 'event' });
343	            return;
344	        }
345	        if (delta.type !== 'signature_delta') ClaudeStreamingAdapter.ignoreProtocolNoise();
346	    }
347	
348	    async handleAssistantCompletion(event) {
349	        await this.ensureTurnStarted();
350	        if (!Array.isArray(event.message?.content)) {
351	            await this.emitProtocolError('assistant message missing content');
352	            return;
353	        }
354	        const messageId = event.message.id ?? this.activeMessageId;
355	        if (typeof messageId !== 'string' || messageId.length === 0) throw new Error('Missing Claude assistant message id');
356	        for (const [index, block] of event.message.content.entries()) {
357	            const providerItemId = block.id ?? `${messageId}:${block.type}:${index}`;
358	            if (block.type === 'text' && typeof block.text === 'string') {
359	                const streamedItem = this.streamedTextItems.get(providerItemId);
360	                const separator = streamedItem?.separator ?? (this.turnHasAssistantText ? '\n\n' : '');
361	                if (!streamedItem) {
362	                    await this.onEvent({ itemId: providerItemId, type: 'assistantStarted' });
363	                }
364	                this.turnHasAssistantText = this.turnHasAssistantText || block.text.length > 0;
365	                await this.onEvent({ content: `${separator}${block.text}`, itemId: providerItemId, type: 'assistantCompleted' });
366	                continue;
367	            }
368	            if (block.type === 'thinking') {
369	                const content = typeof block.thinking === 'string' ? block.thinking : '';
370	                const reasoningEvent = {
371	                    ...eventBase(providerItemId, 'reasoning', 'Thinking', 'completed'),
372	                    content,
373	                    details: [content],
374	                    summary: [],
375	                };
376	                await this.onEvent({ event: reasoningEvent, type: 'event' });
377	                continue;
378	            }
379	            if (block.type === 'tool_use') await this.onEvent({ event: claudeToolEvent(block, 'inProgress', providerItemId), type: 'event' });
380	        }
381	        const changedPaths = claudeChangedPaths(event, this.rootPath);
382	        if (changedPaths.length > 0) await this.onEvent({ paths: changedPaths, type: 'changedPaths' });
383	    }
384	
385	    async handleToolResults(event) {
386	        if (!Array.isArray(event.message?.content)) return;
387	        for (const block of event.message.content) {
388	            if (block?.type !== 'tool_result' || typeof block.tool_use_id !== 'string') continue;
389	            const trackedTool = [...this.activeBlocks.values()].find(({ providerItemId }) => providerItemId === block.tool_use_id);
390	            const toolEvent = trackedTool?.block?.type === 'tool_use'
391	                ? claudeToolEvent(trackedTool.block, block.is_error ? 'failed' : 'completed')
392	                : eventBase(block.tool_use_id, 'tool.result', 'Tool result', block.is_error ? 'failed' : 'completed');
393	            toolEvent.output = normalizedContent(block.content) ?? '';
394	            await this.onEvent({ event: toolEvent, type: 'event' });
395	        }
396	    }
397	
398	    async handleResult(event) {
399	        const error = event.is_error === true
400	            ? String(event.error ?? event.result ?? event.message ?? event.errors?.join('\n') ?? 'Claude turn failed')
401	            : null;
402	        const missingSession = !this.turnStarted && (
403	            isClaudeMissingSessionResult(event, this.providerConversationId)
404	            || isMissingSession('claude', event, this.turnStarted)
405	        );
406	        for (const requestId of this.pendingApprovals.keys()) {
407	            this.pendingApprovals.delete(requestId);
408	            await this.onEvent({ requestId, type: 'approvalResolved' });
409	        }
410	        this.activeBlocks.clear();
411	        this.streamedTextItems.clear();
412	        this.activeMessageId = null;
413	        this.pendingQuestions.clear();
414	        this.turnStarted = false;
415	        this.turnHasAssistantText = false;
416	        await this.onEvent({ error, missingSession, type: 'turnCompleted', usage: claudeUsage(event) });
417	    }
418	
419	    static ignoreProtocolNoise() {
420	        // Valid protocol additions need no user-facing event until adapter support exists.
421	    }
422	
423	    async emitProtocolError(content) {
424	        const providerItemId = `error:${this.activeMessageId ?? 'unknown-message'}:${this.protocolErrorSequence}`;
425	        this.protocolErrorSequence += 1;
426	        const event = { ...eventBase(providerItemId, 'error', 'Claude protocol error', 'failed'), content };
427	        await this.onEvent({ event, type: 'event' });
428	    }
429	}
